function _readSpotPriceByChainlink(bytes32 encoding) internal view returns
(uint256) {
    address aggregator;
    uint256 scale;
    uint256 heartbeat;
    assembly {
        aggregator := shr(96, encoding)
        scale := and(shr(32, encoding), 0xffffffffffffffff)
        heartbeat := and(encoding, 0xffffffff)
    }
    (, int256 answer,, uint256 updatedAt,) =
    AggregatorV3Interface(aggregator).latestRoundData();
    if (block.timestamp - updatedAt > heartbeat) revert("expired");
    return uint256(answer) * scale;
}

function intToUint(int256 a) internal pure returns (uint256) {
    if (a < 0) {
        return uint256(-a);
    } else {
        return uint256(a);
    }
}
